const PYTHON_INTEGER_PATTERN = /^[+-]?(?:\d(?:_?\d)*)$/;

export function parsePythonInteger(value) {
  const original = String(value);
  const trimmed = original.replace(/^\s+|\s+$/g, '');

  if (!PYTHON_INTEGER_PATTERN.test(trimmed)) {
    return {
      ok: false,
      value: null,
    };
  }

  const normalized = trimmed.replace(/_/g, '');
  return {
    ok: true,
    value: BigInt(normalized).toString(),
  };
}

class Job {
  constructor(scheduler, interval) {
    this.scheduler = scheduler;
    this.interval = String(interval);
    this.unit = null;
    this.jobFunction = null;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get day() {
    this.unit = 'days';
    return this;
  }

  get week() {
    this.unit = 'weeks';
    return this;
  }

  get monday() {
