    return this;
  }

  get tuesday() {
    this.unit = 'weeks';
    return this;
  }

  get wednesday() {
    this.unit = 'weeks';
    return this;
  }

  get thursday() {
    this.unit = 'weeks';
    return this;
  }

  get friday() {
    this.unit = 'weeks';
    return this;
  }

  get saturday() {
    this.unit = 'weeks';
    return this;
  }

  get sunday() {
    this.unit = 'weeks';
    return this;
  }

  do(jobFunction) {
    this.jobFunction = jobFunction;
    return this;
  }

  toString() {
    return `Job(interval=${this.interval}, unit=${this.unit}, do=<lambda>, args=(), kwargs={})`;
  }
}

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    const job = new Job(this, interval);
    this.jobs.push(job);
    return job;
  }

  getJobs() {
    return [...this.jobs];
  }
}

export function createScheduler() {
  return new Scheduler();
}

import { parsePythonInteger } from './python_int.mjs';

const OPTIONS = new Map([
  ['--a', { name: 'a', metavar: 'A', required: true }],
  ['--b', { name: 'b', metavar: 'B', required: true }],
  ['--c', { name: 'c', metavar: 'C', required: true }],
]);

function baseName(path) {
  const text = String(path ?? '');
  const pieces = text.split(/[\\/]/);
  return pieces[pieces.length - 1] || text;
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function helpText(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C`;
}

function fail(programName, message) {
  console.error(usage(programName));
  console.error(`${programName}: error: ${message}`);
  process.exit(2);
}

function isNegativeNumberToken(token) {
  return /^-\d/.test(token) || /^-\.\d/.test(token);
}

function looksLikeOption(token) {
  return token === '--' || (token.startsWith('-') && !isNegativeNumberToken(token));
}

function resolveLongOption(optionName) {
  if (OPTIONS.has(optionName)) {
    return OPTIONS.get(optionName);
  }

  const matches = [...OPTIONS.entries()].filter(([candidate]) => candidate.startsWith(optionName));
  if (matches.length === 1) {
    return matches[0][1];
  }

  return null;
}

export function parseCommandLine(argv = process.argv) {
  const programName = baseName(argv[1]);
  const tokens = argv.slice(2);
  const values = new Map();
  const unknown = [];
  let optionsEnded = false;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (optionsEnded) {
      unknown.push(token);
      continue;
    }

    if (token === '--') {
      optionsEnded = true;
      continue;
    }

    if (token === '-h' || token === '--help') {
      console.log(helpText(programName));
      process.exit(0);
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const inlineValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const option = resolveLongOption(optionName);

      if (option === null) {
        unknown.push(token);
        continue;
      }

      let rawValue = inlineValue;
      if (rawValue === null) {
        const next = tokens[index + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(programName, `argument --${option.name}: expected one argument`);
        }
        rawValue = next;
        index += 1;
      }

      const parsed = parsePythonInteger(rawValue);
      if (!parsed.ok) {
        fail(programName, `argument --${option.name}: invalid int value: '${String(rawValue).replace(/'/g, "\\'")}'`);
      }
      values.set(option.name, parsed.value);
      continue;
    }

    unknown.push(token);
  }

  const missing = [...OPTIONS.values()].filter((option) => !values.has(option.name));
  if (missing.length > 0) {
    const rendered = missing.map((option) => `--${option.name}`).join(', ');
    fail(programName, `the following arguments are required: ${rendered}`);
  }

  if (unknown.length > 0) {
    fail(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return {
    a: values.get('a'),
    b: values.get('b'),
    c: values.get('c'),
  };
}

