const NON_PRINTABLE_PATTERN = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}]/u;

function hexadecimalEscape(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }
  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function pythonStringRepr(value) {
  const text = String(value);
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let result = quote;

  for (const character of text) {
    if (character === '\\') {
      result += '\\\\';
    } else if (character === quote) {
      result += `\\${quote}`;
    } else if (character === '\n') {
      result += '\\n';
    } else if (character === '\r') {
      result += '\\r';
    } else if (character === '\t') {
      result += '\\t';
    } else if (NON_PRINTABLE_PATTERN.test(character)) {
      result += hexadecimalEscape(character.codePointAt(0));
    } else {
      result += character;
    }
  }

  return `${result}${quote}`;
}

